CREATE TABLE wb.verified_requirement_version(project_id text NOT NULL,batch_id text NOT NULL,requirement_id text NOT NULL,version_id text NOT NULL,source_link_ref text NOT NULL CHECK(btrim(source_link_ref)<>''),source_revision text NOT NULL CHECK(btrim(source_revision)<>''),PRIMARY KEY(project_id,batch_id,requirement_id,version_id),FOREIGN KEY(project_id,batch_id,requirement_id) REFERENCES wb.batch_requirement,FOREIGN KEY(project_id,batch_id,version_id) REFERENCES wb.batch_version);
CREATE TABLE wb.batch_requirement_version(project_id text NOT NULL,batch_id text NOT NULL,requirement_id text NOT NULL,version_id text NOT NULL,PRIMARY KEY(project_id,batch_id,requirement_id,version_id),FOREIGN KEY(project_id,batch_id,requirement_id,version_id) REFERENCES wb.verified_requirement_version);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['verified_requirement_version','batch_requirement_version'] LOOP EXECUTE format('ALTER TABLE wb.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY read_scope ON wb.%I FOR SELECT USING(wb.allowed(project_id,false))',t); EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON wb.%I FOR EACH ROW EXECUTE FUNCTION wb.reject_history_change()',t); END LOOP; END $$;
CREATE POLICY write_scope ON wb.batch_requirement_version FOR INSERT WITH CHECK(wb.allowed(project_id,true));
